<?php
// Generated by mullion — do not edit.
//
// Explains one SQL statement for the Watch tab: Mullion runs this with
// the site's own PHP CLI and writes a JSON request on stdin —
// {conn: {driver, host, port, socket, database, username, password},
//  sql, bindings, analyze, tables} — and reads one JSON object back.
//
// It only ever runs EXPLAIN-style statements: plain EXPLAIN (MySQL,
// MariaDB, PostgreSQL), EXPLAIN QUERY PLAN (SQLite) and SHOWPLAN_XML
// (SQL Server) don't execute the statement. Analyze (SELECT only, which
// Mullion checks first) does run it, inside a READ ONLY transaction that
// is rolled back. Index and row-count lookups are plain catalog reads.
// SQLite files are opened read-only.

declare(strict_types=1);

error_reporting(E_ALL);
ini_set('display_errors', 'stderr');
ini_set('memory_limit', '256M');

function mx_out(array $a): void
{
    echo json_encode($a, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR);
    exit(0);
}

$req = json_decode((string) stream_get_contents(STDIN), true);
if (!is_array($req)) {
    mx_out(['ok' => false, 'error' => 'bad request']);
}
$conn = (array) ($req['conn'] ?? []);
$secret = (string) ($conn['password'] ?? '');

function mx_scrub(string $msg, string $secret): string
{
    if ($secret !== '') {
        $msg = str_replace($secret, '********', $msg);
    }
    return $msg;
}

/** One database handle over PDO, or the native pgsql / SQLite3 extensions when PDO's driver isn't built in. */
final class MxDb
{
    public string $via = '';
    public string $driver;
    private ?PDO $pdo = null;
    /** @var resource|\PgSql\Connection|null */
    private $pg = null;
    private ?SQLite3 $lite = null;

    public function __construct(array $c)
    {
        $this->driver = $d = (string) $c['driver'];
        $host = (string) ($c['host'] ?? '127.0.0.1');
        $port = (int) ($c['port'] ?? 0);
        $db = (string) ($c['database'] ?? '');
        $user = (string) ($c['username'] ?? '');
        $pass = (string) ($c['password'] ?? '');
        $opts = [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 5, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC];
        switch ($d) {
            case 'mysql':
            case 'mariadb':
                if (!extension_loaded('pdo_mysql')) {
                    throw new RuntimeException('this PHP has no pdo_mysql extension');
                }
                $dsn = !empty($c['socket']) ? 'mysql:unix_socket=' . $c['socket'] : 'mysql:host=' . $host . ';port=' . $port;
                $this->pdo = new PDO($dsn . ';dbname=' . $db . ';charset=utf8mb4', $user, $pass, $opts);
                $this->via = 'pdo_mysql';
                break;
            case 'pgsql':
                if (extension_loaded('pdo_pgsql')) {
                    $this->pdo = new PDO('pgsql:host=' . $host . ';port=' . $port . ';dbname=' . $db . ';connect_timeout=5', $user, $pass, $opts);
                    $this->via = 'pdo_pgsql';
                } elseif (function_exists('pg_connect')) {
                    $q = static fn ($v) => "'" . str_replace(['\\', "'"], ['\\\\', "\\'"], (string) $v) . "'";
                    $cs = 'host=' . $q($host) . ' port=' . $port . ' dbname=' . $q($db) . ' user=' . $q($user) . ' password=' . $q($pass) . ' connect_timeout=5';
                    $pg = @pg_connect($cs, PGSQL_CONNECT_FORCE_NEW);
                    if (!$pg) {
                        $e = error_get_last();
                        throw new RuntimeException('could not connect to PostgreSQL' . ($e ? ': ' . $e['message'] : ''));
                    }
                    $this->pg = $pg;
                    $this->via = 'pgsql';
                } else {
                    throw new RuntimeException('this PHP has neither pdo_pgsql nor pgsql');
                }
                break;
            case 'sqlite':
                if (!is_file($db)) {
                    throw new RuntimeException('the SQLite database ' . $db . ' does not exist');
                }
                if (extension_loaded('pdo_sqlite') && defined('PDO::SQLITE_ATTR_OPEN_FLAGS')) {
                    $this->pdo = new PDO('sqlite:' . $db, null, null, $opts + [PDO::SQLITE_ATTR_OPEN_FLAGS => PDO::SQLITE_OPEN_READONLY]);
                    $this->via = 'pdo_sqlite';
                } elseif (class_exists('SQLite3')) {
                    $this->lite = new SQLite3($db, SQLITE3_OPEN_READONLY);
                    $this->lite->enableExceptions(true);
                    $this->lite->busyTimeout(3000);
                    $this->via = 'sqlite3';
                } else {
                    throw new RuntimeException('this PHP has neither pdo_sqlite nor sqlite3');
                }
                break;
            case 'sqlsrv':
                if (extension_loaded('pdo_sqlsrv')) {
                    // pdo_sqlsrv rejects PDO::ATTR_TIMEOUT ("An unsupported
                    // attribute was designated"): the login timeout goes in
                    // the DSN and the query timeout has its own attribute.
                    $sqlsrvOpts = $opts;
                    unset($sqlsrvOpts[PDO::ATTR_TIMEOUT]);
                    if (defined('PDO::SQLSRV_ATTR_QUERY_TIMEOUT')) {
                        $sqlsrvOpts[PDO::SQLSRV_ATTR_QUERY_TIMEOUT] = 15;
                    }
                    $this->pdo = new PDO('sqlsrv:Server=' . $host . ($port ? ',' . $port : '') . ';Database=' . $db . ';LoginTimeout=5;TrustServerCertificate=1', $user, $pass, $sqlsrvOpts);
                    $this->via = 'pdo_sqlsrv';
                } elseif (extension_loaded('pdo_dblib')) {
                    $this->pdo = new PDO('dblib:host=' . $host . ($port ? ':' . $port : '') . ';dbname=' . $db . ';charset=UTF-8', $user, $pass, $opts);
                    $this->via = 'pdo_dblib';
                } else {
                    throw new RuntimeException('this PHP has neither pdo_sqlsrv nor pdo_dblib');
                }
                break;
            default:
                throw new RuntimeException('unsupported driver ' . $d);
        }
    }

    /** @return list<array<string,mixed>> */
    public function rows(string $sql): array
    {
        if ($this->pdo) {
            $st = $this->pdo->query($sql);
            $out = [];
            do {
                if ($st->columnCount() > 0) {
                    foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
                        $out[] = $r;
                    }
                    break;
                }
            } while ($st->nextRowset());
            return $out;
        }
        if ($this->pg) {
            $res = @pg_query($this->pg, $sql);
            if ($res === false) {
                throw new RuntimeException((string) pg_last_error($this->pg));
            }
            return pg_fetch_all($res) ?: [];
        }
        $res = $this->lite->query($sql);
        $out = [];
        while ($res && ($r = $res->fetchArray(SQLITE3_ASSOC)) !== false) {
            $out[] = $r;
        }
        return $out;
    }

    public function exec(string $sql): void
    {
        if ($this->pdo) {
            $this->pdo->exec($sql);
        } elseif ($this->pg) {
            if (@pg_query($this->pg, $sql) === false) {
                throw new RuntimeException((string) pg_last_error($this->pg));
            }
        } else {
            $this->lite->exec($sql);
        }
    }

    public function quote(string $s): string
    {
        if ($this->pdo && $this->via !== 'pdo_dblib') {
            $q = $this->pdo->quote($s);
            if ($q !== false) {
                return $q;
            }
        }
        if ($this->pg) {
            return pg_escape_literal($this->pg, $s);
        }
        if ($this->lite) {
            return "'" . SQLite3::escapeString($s) . "'";
        }
        return "'" . str_replace("'", "''", $s) . "'";
    }

    /** Quotes an identifier (the names come from Mullion, already checked). */
    public function ident(string $name): string
    {
        $parts = explode('.', $name);
        foreach ($parts as &$p) {
            switch ($this->driver) {
                case 'mysql':
                case 'mariadb':
                    $p = '`' . str_replace('`', '``', $p) . '`';
                    break;
                case 'sqlsrv':
                    $p = '[' . str_replace(']', ']]', $p) . ']';
                    break;
                default:
                    $p = '"' . str_replace('"', '""', $p) . '"';
            }
        }
        return implode('.', $parts);
    }

    /** Fills the "?" placeholders (outside quotes) with the bindings, as Laravel's toRawSql does. */
    public function bind(string $sql, array $bindings): string
    {
        $out = '';
        $n = strlen($sql);
        $i = 0;
        $k = 0;
        $quote = '';
        while ($i < $n) {
            $c = $sql[$i];
            if ($quote !== '') {
                $out .= $c;
                if ($c === '\\' && $quote === "'" && ($this->driver === 'mysql' || $this->driver === 'mariadb') && $i + 1 < $n) {
                    $out .= $sql[++$i];
                } elseif ($c === $quote) {
                    $quote = '';
                }
                $i++;
                continue;
            }
            if ($c === "'" || $c === '"' || $c === '`') {
                $quote = $c;
            } elseif ($c === '[' && $this->driver === 'sqlsrv') {
                $quote = ']';
            } elseif ($c === '?' && $i + 1 < $n && $sql[$i + 1] === '?') {
                $out .= '?'; // Laravel escapes PostgreSQL's ? operators as ??
                $i += 2;
                continue;
            } elseif ($c === '?') {
                $out .= $this->literal($bindings[$k] ?? null);
                $k++;
                $i++;
                continue;
            }
            $out .= $c;
            $i++;
        }
        return $out;
    }

    private function literal($v): string
    {
        if ($v === null) {
            return 'NULL';
        }
        if (is_bool($v)) {
            return $this->driver === 'pgsql' ? ($v ? 'true' : 'false') : ($v ? '1' : '0');
        }
        if (is_int($v) || is_float($v)) {
            return (string) $v;
        }
        if (is_array($v)) {
            $v = json_encode($v);
        }
        return $this->quote((string) $v);
    }
}

function mx_first(array $rows)
{
    if (!$rows) {
        return null;
    }
    $r = $rows[0];
    return reset($r);
}

function mx_tables(MxDb $db, array $tables): object
{
    $out = [];
    foreach ($tables as $t) {
        $t = (string) $t;
        if (!preg_match('/^[A-Za-z0-9_$]+(\.[A-Za-z0-9_$]+)?$/', $t)) {
            continue;
        }
        $info = ['rows' => null, 'indexes' => [], 'columns' => (object) []];
        try {
            switch ($db->driver) {
                case 'mysql':
                case 'mariadb':
                    [$schema, $name] = strpos($t, '.') !== false ? explode('.', $t, 2) : [null, $t];
                    $sch = $schema === null ? 'DATABASE()' : $db->quote($schema);
                    $info['rows'] = mx_first($db->rows('SELECT TABLE_ROWS FROM information_schema.TABLES WHERE TABLE_SCHEMA = ' . $sch . ' AND TABLE_NAME = ' . $db->quote($name)));
                    $idx = [];
                    foreach ($db->rows('SHOW INDEX FROM ' . $db->ident($t)) as $r) {
                        $k = $r['Key_name'];
                        $idx[$k] = $idx[$k] ?? ['name' => $k, 'unique' => (int) $r['Non_unique'] === 0, 'primary' => $k === 'PRIMARY', 'columns' => [], 'cardinality' => null];
                        $idx[$k]['columns'][(int) $r['Seq_in_index'] - 1] = $r['Column_name'] ?? ('(' . ($r['Expression'] ?? 'expression') . ')');
                        if ((int) $r['Seq_in_index'] === 1) {
                            $idx[$k]['cardinality'] = $r['Cardinality'] === null ? null : (int) $r['Cardinality'];
                        }
                    }
                    $info['indexes'] = array_values($idx);
                    $cols = [];
                    foreach ($db->rows('SELECT COLUMN_NAME AS c, DATA_TYPE AS t FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = ' . $sch . ' AND TABLE_NAME = ' . $db->quote($name) . ' ORDER BY ORDINAL_POSITION') as $r) {
                        $cols[$r['c']] = $r['t'];
                    }
                    $info['columns'] = (object) $cols;
                    break;
                case 'pgsql':
                    $rel = 'to_regclass(' . $db->quote($t) . ')';
                    $rows = mx_first($db->rows('SELECT c.reltuples::bigint FROM pg_class c WHERE c.oid = ' . $rel));
                    if ($rows === null) {
                        break; // not a table (a CTE name, a view's alias…)
                    }
                    if ((int) $rows < 0) {
                        // Never analyzed: count, but not forever.
                        $rows = mx_first($db->rows('SELECT count(*) FROM (SELECT 1 FROM ' . $db->ident($t) . ' LIMIT 1000001) s'));
                    }
                    $info['rows'] = (int) $rows;
                    $q = 'SELECT i.relname AS name, x.indisunique AS uniq, x.indisprimary AS prim,'
                        . ' ARRAY_TO_STRING(ARRAY(SELECT pg_get_indexdef(x.indexrelid, k + 1, true) FROM generate_series(0, x.indnkeyatts - 1) k ORDER BY k), chr(31)) AS cols,'
                        . ' pg_get_indexdef(x.indexrelid) AS def'
                        . ' FROM pg_index x JOIN pg_class i ON i.oid = x.indexrelid WHERE x.indrelid = ' . $rel . ' ORDER BY i.relname';
                    foreach ($db->rows($q) as $r) {
                        $info['indexes'][] = [
                            'name' => $r['name'],
                            'unique' => in_array($r['uniq'], [true, 't', 1, '1'], true),
                            'primary' => in_array($r['prim'], [true, 't', 1, '1'], true),
                            'columns' => array_map(static fn ($c) => trim($c, '"'), explode(chr(31), (string) $r['cols'])),
                            'def' => $r['def'],
                        ];
                    }
                    $cols = [];
                    foreach ($db->rows('SELECT a.attname AS c, format_type(a.atttypid, a.atttypmod) AS t FROM pg_attribute a WHERE a.attrelid = ' . $rel . ' AND a.attnum > 0 AND NOT a.attisdropped ORDER BY a.attnum') as $r) {
                        $cols[$r['c']] = $r['t'];
                    }
                    $info['columns'] = (object) $cols;
                    break;
                case 'sqlite':
                    $exists = mx_first($db->rows("SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = " . $db->quote($t)));
                    if (!(int) $exists) {
                        break;
                    }
                    $info['rows'] = (int) mx_first($db->rows('SELECT count(*) FROM (SELECT 1 FROM ' . $db->ident($t) . ' LIMIT 1000001)'));
                    $cols = [];
                    $pk = [];
                    foreach ($db->rows('PRAGMA table_info(' . $db->ident($t) . ')') as $r) {
                        $cols[$r['name']] = $r['type'];
                        if ((int) $r['pk'] > 0) {
                            $pk[(int) $r['pk'] - 1] = $r['name'];
                        }
                    }
                    $info['columns'] = (object) $cols;
                    $hasPkIndex = false;
                    foreach ($db->rows('PRAGMA index_list(' . $db->ident($t) . ')') as $r) {
                        $c = [];
                        foreach ($db->rows('PRAGMA index_info(' . $db->ident((string) $r['name']) . ')') as $ir) {
                            $c[(int) $ir['seqno']] = $ir['name'] ?? '(expression)';
                        }
                        ksort($c);
                        $prim = ($r['origin'] ?? '') === 'pk';
                        $hasPkIndex = $hasPkIndex || $prim;
                        $info['indexes'][] = ['name' => $r['name'], 'unique' => (int) $r['unique'] === 1, 'primary' => $prim, 'columns' => array_values($c)];
                    }
                    if ($pk && !$hasPkIndex) {
                        ksort($pk);
                        // INTEGER PRIMARY KEY is the rowid: no index entry, but indexed all the same.
                        $info['indexes'][] = ['name' => 'PRIMARY', 'unique' => true, 'primary' => true, 'columns' => array_values($pk)];
                    }
                    break;
                case 'sqlsrv':
                    $oid = 'OBJECT_ID(' . 'N' . $db->quote($t) . ')';
                    $rows = mx_first($db->rows('SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = ' . $oid . ' AND p.index_id IN (0, 1)'));
                    if ($rows === null) {
                        break;
                    }
                    $info['rows'] = (int) $rows;
                    $idx = [];
                    foreach ($db->rows('SELECT i.name AS name, i.is_unique AS uniq, i.is_primary_key AS prim, c.name AS col, ic.is_included_column AS inc FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = ' . $oid . ' ORDER BY i.name, ic.is_included_column, ic.key_ordinal') as $r) {
                        $k = (string) $r['name'];
                        $idx[$k] = $idx[$k] ?? ['name' => $k, 'unique' => (bool) $r['uniq'], 'primary' => (bool) $r['prim'], 'columns' => [], 'include' => []];
                        if ((int) $r['inc']) {
                            $idx[$k]['include'][] = $r['col'];
                        } else {
                            $idx[$k]['columns'][] = $r['col'];
                        }
                    }
                    $info['indexes'] = array_values($idx);
                    $cols = [];
                    foreach ($db->rows('SELECT c.name AS c, t.name AS t FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = ' . $oid . ' ORDER BY c.column_id') as $r) {
                        $cols[$r['c']] = $r['t'];
                    }
                    $info['columns'] = (object) $cols;
                    break;
            }
        } catch (Throwable $e) {
            $info['error'] = $e->getMessage();
        }
        $out[$t] = $info;
    }
    return (object) $out;
}

try {
    $db = new MxDb($conn);
    $sql = rtrim(trim((string) ($req['sql'] ?? '')), ';');
    $bound = $db->bind($sql, (array) ($req['bindings'] ?? []));
    $analyze = !empty($req['analyze']);
    $res = ['ok' => true, 'driver' => $db->driver, 'via' => $db->via, 'sql' => $bound, 'explain' => []];
    switch ($db->driver) {
        case 'mysql':
        case 'mariadb':
            $ver = (string) mx_first($db->rows('SELECT VERSION()'));
            $res['server'] = $ver;
            $maria = stripos($ver, 'mariadb') !== false;
            if ($maria) {
                $res['driver'] = 'mariadb';
            }
            $res['explain']['tabular'] = $db->rows('EXPLAIN ' . $bound);
            $warn = [];
            foreach ($db->rows('SHOW WARNINGS') as $w) {
                // Notes (1003 = the rewritten query, 1276 = a resolved outer reference…) are noise.
                if (strcasecmp((string) ($w['Level'] ?? ''), 'Note') !== 0) {
                    $warn[] = ['code' => (string) ($w['Code'] ?? ''), 'message' => (string) ($w['Message'] ?? '')];
                }
            }
            $res['explain']['warnings'] = $warn;
            try {
                $res['explain']['json'] = (string) mx_first($db->rows('EXPLAIN FORMAT=JSON ' . $bound));
            } catch (Throwable $e) {
                $res['explain']['jsonError'] = $e->getMessage();
            }
            if ($analyze) {
                $db->exec($maria ? 'SET SESSION max_statement_time = 15' : 'SET SESSION max_execution_time = 15000');
                $db->exec('START TRANSACTION READ ONLY');
                try {
                    $res['explain']['analyze'] = (string) mx_first($db->rows(($maria ? 'ANALYZE FORMAT=JSON ' : 'EXPLAIN ANALYZE ') . $bound));
                } finally {
                    $db->exec('ROLLBACK');
                }
            }
            break;
        case 'pgsql':
            $res['server'] = (string) mx_first($db->rows('SHOW server_version'));
            $db->exec('BEGIN READ ONLY');
            try {
                $db->exec("SET LOCAL statement_timeout = '15s'");
                $opts = $analyze ? '(ANALYZE, BUFFERS, FORMAT JSON)' : '(FORMAT JSON)';
                $res['explain']['json'] = (string) mx_first($db->rows('EXPLAIN ' . $opts . ' ' . $bound));
            } finally {
                $db->exec('ROLLBACK');
            }
            break;
        case 'sqlite':
            $res['server'] = (string) mx_first($db->rows('SELECT sqlite_version()'));
            $res['explain']['rows'] = $db->rows('EXPLAIN QUERY PLAN ' . $bound);
            break;
        case 'sqlsrv':
            $res['server'] = (string) mx_first($db->rows("SELECT CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(64))"));
            $db->exec('SET TEXTSIZE 2147483647');
            $db->exec('SET SHOWPLAN_XML ON');
            try {
                $res['explain']['xml'] = (string) mx_first($db->rows($bound));
            } finally {
                $db->exec('SET SHOWPLAN_XML OFF');
            }
            break;
    }
    if ($db->driver === 'pgsql') {
        // Outside a transaction: one failed lookup mustn't abort the rest.
        $db->exec("SET statement_timeout = '10s'");
    }
    $res['tables'] = mx_tables($db, (array) ($req['tables'] ?? []));
    mx_out($res);
} catch (Throwable $e) {
    mx_out(['ok' => false, 'error' => mx_scrub($e->getMessage(), $secret)]);
}
